import os
import ast
import sys
import json
import hashlib
import datetime
import importlib.util
from pathlib import Path

# ==================================================================================================
# def UTILITIES
# ==================================================================================================

def def_now():
    return datetime.datetime.now().isoformat(timespec="seconds")

def def_norm(path):
    return str(Path(path)).replace("/", "\\").lower()

def def_sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(1024 * 1024), b""):
            h.update(b)
    return h.hexdigest()

def def_ast_fingerprint(path):
    text = Path(path).read_text(encoding="utf-8", errors="replace")
    tree = ast.parse(text)
    parts = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            parts.append("DEF:" + node.name)
        elif isinstance(node, ast.ClassDef):
            parts.append("CLS:" + node.name)
        elif isinstance(node, ast.Import):
            for a in node.names:
                parts.append("IMP:" + a.name)
        elif isinstance(node, ast.ImportFrom):
            parts.append("FROM:" + str(node.module or ""))
    return hashlib.sha256("\n".join(sorted(parts)).encode("utf-8", errors="replace")).hexdigest()

def def_load_json(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))

def def_write_json(path, payload):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")

# ==================================================================================================
# def FIREWALL CLASS
# ==================================================================================================

class VIA_RuntimeImportFirewall:

    def __init__(self, seal_path, provenance_path=None, strict=True):
        self.seal_path = Path(seal_path)
        self.seal = def_load_json(self.seal_path)
        self.strict = strict
        self.provenance_path = Path(provenance_path) if provenance_path else None
        self.events = []

        self.authority = {
            item["module_id"]: item
            for item in self.seal.get("authority", [])
        }

        self.blocked_paths = {
            def_norm(item["blocked_path"]): item
            for item in self.seal.get("blocklist", [])
        }

    def def_event(self, level, module_id, path, status, message):
        event = {
            "time": def_now(),
            "level": level,
            "module_id": module_id,
            "path": str(path),
            "status": status,
            "message": message
        }
        self.events.append(event)
        return event

    def def_verify_path_allowed(self, module_id, path):
        p = Path(path)
        n = def_norm(p)

        if n in self.blocked_paths:
            info = self.blocked_paths[n]
            return False, "BLOCKED_NON_CANONICAL: " + info.get("reason", "")

        auth = self.authority.get(module_id)

        if not auth:
            return False, "MODULE_NOT_IN_AUTHORITY"

        if def_norm(auth["canonical_path"]) != n:
            return False, "NON_CANONICAL_PATH"

        return True, "PATH_ALLOWED"

    def def_verify_hash_ast(self, module_id, path):
        auth = self.authority.get(module_id)

        if not auth:
            return False, "MODULE_NOT_IN_AUTHORITY"

        runtime_hash = def_sha256(path)
        runtime_ast = def_ast_fingerprint(path)

        if runtime_hash != auth.get("approved_hash", ""):
            return False, "HASH_MISMATCH"

        if runtime_ast != auth.get("approved_ast_fingerprint", ""):
            return False, "AST_FINGERPRINT_MISMATCH"

        return True, "HASH_AST_OK"

    def def_verify_module_file(self, module_id, path):
        p = Path(path)

        if not p.exists():
            self.def_event("ERROR", module_id, p, "FAIL", "FILE_NOT_FOUND")
            if self.strict:
                raise RuntimeError(f"RuntimeImportFirewall: FILE_NOT_FOUND {p}")
            return False

        ok, msg = self.def_verify_path_allowed(module_id, p)

        if not ok:
            self.def_event("ERROR", module_id, p, "FAIL", msg)
            if self.strict:
                raise RuntimeError(f"RuntimeImportFirewall: {msg} {p}")
            return False

        ok, msg = self.def_verify_hash_ast(module_id, p)

        if not ok:
            self.def_event("ERROR", module_id, p, "FAIL", msg)
            if self.strict:
                raise RuntimeError(f"RuntimeImportFirewall: {msg} {p}")
            return False

        self.def_event("INFO", module_id, p, "PASS", "CANONICAL_HASH_AST_OK")
        return True

    def def_safe_import_from_path(self, module_id, path):
        self.def_verify_module_file(module_id, path)

        p = Path(path)
        spec = importlib.util.spec_from_file_location(module_id, str(p))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)

        self.def_event("INFO", module_id, p, "IMPORTED", "SAFE_IMPORT_COMPLETE")
        return mod

    def def_write_provenance(self):
        if not self.provenance_path:
            return None

        payload = {
            "generated": def_now(),
            "seal_path": str(self.seal_path),
            "python_executable": sys.executable,
            "cwd": os.getcwd(),
            "sys_path": sys.path,
            "events": self.events
        }

        def_write_json(self.provenance_path, payload)
        return payload

# ==================================================================================================
# def SIMPLE API
# ==================================================================================================

def def_verify_runtime(seal_path, modules_to_verify, provenance_path=None, strict=True):
    fw = VIA_RuntimeImportFirewall(
        seal_path=seal_path,
        provenance_path=provenance_path,
        strict=strict
    )

    results = []

    for item in modules_to_verify:
        module_id = item["module_id"]
        path = item["path"]
        ok = fw.def_verify_module_file(module_id, path)
        results.append({
            "module_id": module_id,
            "path": path,
            "ok": ok
        })

    fw.def_write_provenance()
    return results

